import { ToolDefinition } from "../types/index.js";
import { callNetsuiteRestlet } from "../utils/api.js";

export const runFunctionTool: ToolDefinition = {
    name: "netsuite_run_function",
    description:
        "Run a specific function from a module in NetSuite and return the execution result. " +
        "Supports dot notation in functionName to call functions nested inside exported objects (e.g., '__test.func1'). " +
        "To inspect NetSuite execution logs generated by this call, pair it with netsuite_get_run_function_logs.",
    meta: {
        isDestructive: true,
        requiresSdf: false
    },
    inputSchema: {
        type: "object",
        properties: {
            filePath: {
                type: "string",
                description: "Path to the SuiteScript module in the File Cabinet (e.g., '/SuiteScripts/myModule.js')."
            },
            functionName: {
                type: "string",
                description: "Name of the exported function to execute. Supports dot notation for nested objects (e.g., 'myFunc' or '__test.func1')."
            },
            args: {
                type: "array",
                items: {},
                description: "Arguments array to pass to the function."
            }
        },
        required: ["filePath", "functionName", "args"]
    },
    execute: async (args: { filePath: string; functionName: string; args: any[] }) => {
        try {
            const payload = { action: "RUN_FUNCTION", ...args };
            const response = await callNetsuiteRestlet(payload);
            return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
        } catch (error: any) {
            return { content: [{ type: "text", text: `RESTlet Error: ${error.message}` }] };
        }
    }
};
